Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".

Notation amem := (word -> option byte).

Definition z4_body_case (hi : bool) : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp : word) (b0 b1 b2 b3 : word) (j5 j7 j8 j9 j11 j12 j13 j14 j23 j28 j29 j30 : word)
         (SP DT4 DBL DBH SBL SBH DST dcap SS n IP0 IP1 IP2 IP3 OP0 OP1 OP2 OP3 OLIM : Z) (obuf tbl sbuf : list byte),
    mem_inv asegs mm ->
    bytes_at asegs mm DT4 tbl -> Z.of_nat (length tbl) = 8192 -> ztab_fact asegs mm DT4 8192 4 [(2, 0, 11); (3, 1, 2)] ->
    u8arr asegs mm DST obuf -> Z.of_nat (length obuf) = dcap ->
    bytes_at asegs mm SS sbuf -> Z.of_nat (length sbuf) = n ->
    rw_cells asegs mm (SP + 120) [C8 (Z_to_bv 64 OLIM); C8 (Z_to_bv 64 0xfdd0)] ->
    rw_cells asegs mm (SP + 296) [C8 (Z_to_bv 64 DT4); C8 (Z_to_bv 64 0x20d84)] ->
    wr_at asegs mm (SP + 120) 200 -> stk asegs mm (SP + 120) (SP + 320) ->
    (* [comment removed for export] *)
    unpoisoned mm DBL DBH -> DBL <= DT4 -> DT4 + 8192 <= DBH ->
    unpoisoned mm DST (DST + dcap) -> unpoisoned mm SBL SBH -> SBL <= SS -> SS + n <= SBH ->
    rng RNG DT4 8192 -> rng RNG DST dcap -> rng RNG SS n -> rng RNG (SP + 120) 200 -> rng_aimg RNG ->
    rng RNG (shad DBL) (shlen (DBH - DBL + 7)) -> rng RNG (shad DST) (shlen (dcap + 7)) -> rng RNG (shad SBL) (shlen (SBH - SBL + 7)) ->
    DBL mod 8 = 0 -> DST mod 8 = 0 -> SBL mod 8 = 0 ->
    (* [comment removed for export] *)
    0x60d000 <= DT4 -> DT4 + 8192 <= 2^47 -> 0x60d000 <= DST -> DST + dcap <= 2^47 -> 0x60d000 <= SS -> SS + n <= 2^47 ->
    0x10007fff8000 <= SP -> SP + 576 <= 2^47 -> 0x60d000 <= DBL -> DBH <= 2^47 -> 0x60d000 <= SBL -> SBH <= 2^47 ->
    (if hi then 0x10007fff8000 <= DST else DST + dcap <= 0x7fff7000) ->
    apart DST dcap DT4 8192 -> apart DST dcap SS n -> apart DST dcap (SP + 120) 200 -> apart SS n (SP + 120) 200 ->
    apart DT4 8192 (SP + 120) 200 ->
    (* [comment removed for export] *)
    SS + 7 <= IP0 -> IP0 + 8 <= SS + n -> SS + 7 <= IP1 -> IP1 + 8 <= SS + n ->
    SS + 7 <= IP2 -> IP2 + 8 <= SS + n -> SS + 7 <= IP3 -> IP3 + 8 <= SS + n ->
    DST <= OP0 -> OP0 + 10 <= DST + dcap -> DST <= OP1 -> OP1 + 10 <= DST + dcap ->
    DST <= OP2 -> OP2 + 10 <= DST + dcap -> DST <= OP3 -> OP3 + 10 <= DST + dcap ->
    0 <= OLIM < 2^47 ->
    (forall (mm' : amem) (b0' b1' b2' b3' : word) (nb0 nb1 nb2 nb3 d0 d1 d2 d3 : Z)
            (k5 k7 k8 k9 k11 k12 k13 k14 k23 k28 k29 k30 : word),
       munch [(DST, DST + dcap); (SP + 136, SP + 296); (SP + 312, SP + 320)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       stk asegs mm' (SP + 120) (SP + 320) ->
       (exists obuf', u8arr asegs mm' DST obuf' /\ length obuf' = length obuf) ->
       0 <= nb0 <= 7 -> 0 <= nb1 <= 7 -> 0 <= nb2 <= 7 -> 0 <= nb3 <= 7 ->
       5 <= d0 <= 10 -> 5 <= d1 <= 10 -> 5 <= d2 <= 10 -> 5 <= d3 <= 10 ->
       evtF asegs RNG Q (MS (mkR (Z_to_bv 64 (IP3 - nb3)) (Z_to_bv 64 SP) gp tp k5 (Z_to_bv 64 (OP0 + d0)) k7 k8 k9 (Z_to_bv 64 OLIM)
                                 k11 k12 k13 k14 (Z_to_bv 64 (OP3 + d3)) (Z_to_bv 64 (OP2 + d2)) (Z_to_bv 64 (OP1 + d1))
                                 (Z_to_bv 64 (IP0 - nb0)) (Z_to_bv 64 (IP2 - nb2)) (Z_to_bv 64 DT4) b2' b0' k23 b3'
