(* [comment removed for export] *)
Ltac z4_bounds :=
  lazymatch goal with
  | |- 0 <= bv_unsigned (ev ?E ?j) mod 2 ^ 64 / 2 ^ (3 mod 64) <= 7 =>
      let H := fresh "H" in let HR := fresh "HR" in
      kx_range (EVar j) H;
      pose proof (bv_unsigned_in_range 64 (ev E j)) as HR; unfold bv_modulus in HR; change (2 ^ Z.of_N 64) with (2^64) in HR;
      rewrite (Z.mod_small _ _ HR);
      change (2 ^ (3 mod 64)) with 8;
      exact (z4_nb_bound _ H)
  | |- 5 <= bv_unsigned (ev ?E ?j1) + (bv_unsigned (ev ?E ?j2) + (bv_unsigned (ev ?E ?j3) +
            (bv_unsigned (ev ?E ?j4) + bv_unsigned (ev ?E ?j5)))) <= 10 =>
      let H1 := fresh "H" in let H2 := fresh "H" in let H3 := fresh "H" in let H4 := fresh "H" in let H5 := fresh "H" in
      kx_range (EVar j1) H1; kx_range (EVar j2) H2; kx_range (EVar j3) H3; kx_range (EVar j4) H4; kx_range (EVar j5) H5;
      exact (z4_d_bound _ _ _ _ _ H1 H2 H3 H4 H5)
  end.

